"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"यूराल पर्वतों से प्रशांत महासागर तक। चीन के आकाशी ड्रैगन यहीं से आए, और साइबेरिया व मध्य एशिया स्लाव आत्माओं की धरती हैं।",
"Африка":"अफ़्रीका",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"यहाँ, नील के किनारे, दुआत के द्वार खड़े हैं — मिस्री देवताओं और रेगिस्तानी आत्माओं का घर।",
"Северная Америка":"उत्तरी अमेरिका",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"पंखों वाले सर्पों की धरती: एज़्टेक देवता और आत्माएँ मेक्सिको की घाटी से निकलीं।",
"Южная Америка":"दक्षिणी अमेरिका",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"जंगल, एंडीज़ और अमेज़न। एज़्टेक आत्माएँ यहाँ तक बिखर गईं — ठेठ टिएरा डेल फ़्यूगो तक।",
"Австралия и Океания":"ऑस्ट्रेलिया और ओशिनिया",
"Своих мифологий у Ордена здесь пока нет: все духи Австралии и Океании — гости, которых занесла Перепутица.":"यहाँ संघ की अपनी कोई पौराणिक कथा अभी नहीं है: ऑस्ट्रेलिया और ओशिनिया की सारी आत्माएँ महा-उलझन से आए मेहमान हैं।",
"Антарктида":"अंटार्कटिका",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"यहाँ सिर्फ़ पेंगुइन और बर्फ़ीली आत्माएँ हैं। द्वार यहाँ नहीं खुलते — शिकारियों के लिए भी बहुत ठंड है।",
