"У каждой мифологии Перепутицы — свой клан Ордена. Кланы держат Капища: поставь своего духа защитником — и Капище окрасится цветом твоего клана, а тебе каждый день будет приходить дань. Выбор — навсегда.":"महा-उलझन की हर पौराणिक कथा का संघ में अपना दल है। दल कापिश्चे थामे रखते हैं: अपनी आत्मा को रक्षक बनाकर खड़ा करो — कापिश्चे तुम्हारे दल के रंग में रंग जाएगा, और तुम्हें हर दिन नज़राना मिलेगा। चुनाव हमेशा के लिए है।",
"Позже":"बाद में",
"Выбор — навсегда: сменить клан потом нельзя.":"चुनाव हमेशा के लिए है: बाद में दल नहीं बदल सकते।",
