"Грива из живого пламени. Говорят, в ночь Перепутицы Жарогривы до утра светили заблудившимся духам всех земель, чтобы те не потерялись совсем.":"जीती-जागती लपटों का अयाल। कहते हैं, महा-उलझन की रात ज़ारोग्रिव सुबह तक हर देश की भटकी आत्माओं के लिए चमकते रहे, ताकि वे हमेशा के लिए खो न जाएँ।",
