"Средиземноморье: Греция, Италия, Испания, Турция":"भूमध्यसागर: यूनान, इटली, स्पेन, तुर्की",
"Скандинавская":"नॉर्स",
"Скандинавия, Исландия, Дания, Германия, Прибалтика":"स्कैंडिनेविया, आइसलैंड, डेनमार्क, जर्मनी, बाल्टिक देश",
