"«Достойно, Ловчий», — {0} склоняет голову. Капище «{1}» освящено тобой до конца дня.":"“शाबाश, शिकारी,” — {0} सिर झुकाता है। कापिश्चे “{1}” दिन के अंत तक तुम्हारे द्वारा पवित्र है।",
