"Поражение":"हार",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"“ताक़तवर होकर आना,” — {0} कहता है। दूसरी टीम आज़माओ: रखवाले के तत्व देखो और उसके दाँवों के लिए ढालें बचाकर रखो।",
