"<b>+1 ★</b> дружбы":"दोस्ती के <b>+1 ★</b>",
"Духи {0} оказались сильнее. Подбери команду против их стихий и попробуй снова — поединки с другом не ограничены.":"{0} की आत्माएँ ज़्यादा ताक़तवर निकलीं। उनके तत्वों के ख़िलाफ़ टीम चुनो और फिर कोशिश करो — दोस्त से द्वंद्व की कोई सीमा नहीं।",
