"Прислужник растворился в тумане. Один из его духов — омрачённый {0} — остался рядом. Его ещё можно спасти!":"सेवक कोहरे में घुल गया। उसकी एक आत्मा — अंधकारमय {0} — पास में रह गई। उसे अब भी बचाया जा सकता है!",
