"Твой прогресс перенесён на другое устройство и продолжается там. На этом устройстве можно начать заново.":"तुम्हारी प्रोग्रेस दूसरे डिवाइस पर ट्रांसफ़र हो गई है और वहीं जारी है। इस डिवाइस पर नए सिरे से शुरू कर सकते हो।",
"Если ты <b>не</b> переносил прогресс — не начинай заново: напиши на почту из «Оферты» (Лавка → Казна) и укажи имя Ловчего и когда это случилось. Прогресс можно вернуть.":"अगर तुमने प्रोग्रेस ट्रांसफ़र <b>नहीं</b> की — तो नए सिरे से शुरू मत करो: “ऑफ़र” (दुकान → ख़ज़ाना) वाले ईमेल पर लिखो और शिकारी का नाम और यह कब हुआ, बताओ। प्रोग्रेस वापस मिल सकती है।",
