"Текущий прогресс на этом устройстве будет заменён.":"इस डिवाइस की मौजूदा प्रोग्रेस बदल दी जाएगी।",
"Вводи только код со своего же устройства. Если код прислал кто-то другой — это может быть обман.":"सिर्फ़ अपने ही डिवाइस का कोड डालो। अगर कोड किसी और ने भेजा है — तो यह धोखा हो सकता है।",
"Перенести":"ट्रांसफ़र करो",
"Код — 12 букв и цифр":"कोड — 12 अक्षर और अंक",
"Прогресс перенесён!":"प्रोग्रेस ट्रांसफ़र हो गई!",
"Код переноса":"ट्रांसफ़र कोड",
"Введи этот код на новом устройстве: при первом запуске — «У меня уже есть прогресс», или «Настройки → Перенести прогресс сюда». Код действует 30 минут и один раз.":"यह कोड नए डिवाइस पर डालो: पहली बार खोलने पर — “मेरे पास पहले से प्रोग्रेस है”, या “सेटिंग्स → प्रोग्रेस यहाँ लाओ”। कोड 30 मिनट और एक बार चलता है।",
"После переноса прогресс продолжится на новом устройстве, а здесь можно будет начать заново.":"ट्रांसफ़र के बाद प्रोग्रेस नए डिवाइस पर जारी रहेगी, और यहाँ नए सिरे से शुरू कर सकोगे।",
"<b>Никому не сообщай этот код.</b> По нему забирают весь прогресс — духов, монеты и покупки. Орден, модераторы и друзья никогда не просят код; «подарок за код» — это обман.":"<b>यह कोड किसी को मत बताना।</b> इससे पूरी प्रोग्रेस ले ली जाती है — आत्माएँ, सिक्के और ख़रीदारी। संघ, मॉडरेटर और दोस्त कभी कोड नहीं माँगते; “कोड के बदले तोहफ़ा” — धोखा है।",
