"Бой через":"लड़ाई शुरू होने में",
"Соперник — живой Ловчий. Тапай — быстрая атака, она копит энергию; полная шкала — «Приём». Щиты берегут от его приёмов.":"विरोधी — असली शिकारी। टैप करो — तेज़ हमला, इससे ऊर्जा भरती है; पूरा मीटर — “दाँव”। ढालें उसके दाँवों से बचाती हैं।",
