"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"रेटिंग विरोधी पर निर्भर है: ताक़तवर पर जीत बहुत देती है, कमज़ोर पर — थोड़ा; कमज़ोर से हार ज़्यादा महँगी पड़ती है। तुम्हारी लीग में बराबर वाले पर जीत — +{0}, हार — −{1}; लीग जितनी ऊँची, चढ़ाई उतनी धीमी। लीग से नीचे भी गिर सकते हो। लीग का इनाम सीज़न में एक बार मिलता है। नए सीज़न की शुरुआत में {2} से ऊपर की रेटिंग आधी हो जाती है, और पिछले सीज़न की सबसे ऊँची लीग के लिए संघ संदूक देता है। लीग “{3}”, “{4}” और “{5}” में — कवच भी।",
