"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"लीग में असली शिकारी लड़ते हैं: ताक़तवर विरोधी पर जीत कमज़ोर से ज़्यादा रेटिंग देती है।",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"दरारें हर घंटे कापिश्चे के पास खुलती हैं: तीन आत्माओं की टीम बनाओ।",
"Сияющие духи редки — их выдают искры вокруг.":"चमकीली आत्माएँ दुर्लभ हैं — आसपास की चिंगारियाँ उन्हें पहचानने में मदद करती हैं।",
"Коконы греются шагами: одновременно можно греть три.":"कोकून क़दमों से गर्म होते हैं: एक साथ तीन गर्म कर सकते हो।",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"जॉयस्टिक से चलो: हल्का झुकाव — चलना, पूरा — दौड़ना। कोकून के किलोमीटर भी वैसे ही गिने जाते हैं।",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"विश्व एटलस हर आधे घंटे में धरती के किसी भी कोने तक ले जाता है, और महा-उलझन के द्वार — तुरंत।",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"दिन के क्वेस्ट आधी रात को बदलते हैं, और तीनों पूरे करने पर दिन का संदूक मिलता है।",
"Поставь защитника на Капище своего клана — он принесёт искры.":"अपने दल के कापिश्चे पर रक्षक रखो — वह चिंगारियाँ लाएगा।",
