"духов":"आत्माएँ",
"поймано":"पकड़ी गईं",
"Сохрани прогресс":"प्रोग्रेस सेव करो",
"Другой аккаунт":"दूसरा अकाउंट",
"Гость играет только на этом устройстве — привяжи вход, чтобы не потерять прогресс":"गेस्ट सिर्फ़ इसी डिवाइस पर खेलता है — प्रोग्रेस न खोने के लिए लॉग इन जोड़ो",
"Привяжи вход — и прогресс откроется на любом устройстве":"लॉग इन जोड़ो — और प्रोग्रेस किसी भी डिवाइस पर खुलेगी",
"Текущий прогресс останется в своей учётной записи":"मौजूदा प्रोग्रेस अपने अकाउंट में रहेगी",
"вход":"लॉग इन",
"Открываю {0}…":"{0} खुल रहा है…",
