"Прогресс останется в учётной записи — вернуться в неё можно тем же входом. На этом устройстве начнётся новая гостевая игра.":"प्रोग्रेस अकाउंट में रहेगी — उसी लॉग इन से वापस आ सकते हो। इस डिवाइस पर नया गेस्ट गेम शुरू होगा।",
"Выйти":"लॉग आउट",
"Выйти из гостевой игры?":"गेस्ट गेम से बाहर निकलें?",
"<b>Прогресс гостя пропадёт навсегда</b> — у гостя нет входа, чтобы вернуться.":"<b>गेस्ट की प्रोग्रेस हमेशा के लिए मिट जाएगी</b> — गेस्ट के पास लौटने के लिए लॉग इन नहीं है।",
"Чтобы сохранить его, сначала привяжи вход через {0}.":"इसे बचाने के लिए पहले {0} से लॉग इन जोड़ो।",
